 v=[("el barrio","o bairro","Soa como “el BA-rrio”.","🏘️"),("el ruido","o barulho","Soa como “el RRUI-do”.","🔊"),("la calma","a calma","Soa como “la KAL-ma”.","😌"),("el ritmo","o ritmo","Soa como “el RRIT-mo”.","🎵"),("el quiosquero","o dono da banca","Soa como “el kios-KÊ-ro”.","📰"),("madrugar","acordar cedo","Soa como “ma-dru-GAR”.","🌅")],
